import{_ as p,o as t,c as e,a3 as _}from"./chunks/framework.DdpBa4_E.js";const l="/ReadBooks/assets/image-005.DzwnLQng.jpg",u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/28-若你对依恋风格还模棱两可.md","filePath":"books/attached/28-若你对依恋风格还模棱两可.md","lastUpdated":1794316978000}'),o={name:"books/attached/28-若你对依恋风格还模棱两可.md"};function i(s,a,r,n,d,c){return t(),e("div",null,[...a[0]||(a[0]=[_('<h3 id="若你对依恋风格还模棱两可" tabindex="-1">若你对依恋风格还模棱两可 <a class="header-anchor" href="#若你对依恋风格还模棱两可" aria-label="Permalink to &quot;若你对依恋风格还模棱两可&quot;">​</a></h3><p>当人们了解依恋风格以后，通常很容易就能判断出自己处于哪一种。有的人会立马回应说：“我属于焦虑型。”“我显然是回避型啊。”或者说“我觉得自己是安全型的。”但还有些人，比较不容易确定自己的依恋风格。如果在两种风格上的得分都比较高，你就需要从下面两个维度，来最终决定自己的依恋风格了：</p><ul><li><p>你对亲密关系的舒适程度（或者说回避程度）。</p></li><li><p>你对伴侣的爱意和恋爱关系，所秉持的关注与投入程度。</p></li></ul><p>布伦南和他的同事将依恋风格通过坐标轴图表展示出来，为我们提供了一个非常有效的途径，通过这种鸟瞰的形式，我们能够很清楚地理解自己的依恋风格。坐标图上的位置就决定了你的依恋风格，正如下图所示：</p><p>依恋风格维度图</p><p><img src="'+l+'" alt="" loading="lazy"></p><ul><li><p>如果你对和伴侣的亲密行为，感到非常享受（也就是处于低回避程度），也并不过度地关注你们之间的关系，以及伴侣是否同样爱你，而是任其自然发展（也就是低焦虑程度），那你就属于安全型。</p></li><li><p>如果你非常渴望亲密关系，渴望与伴侣形影不离（也就是低回避程度），但同时你又对关系的最终走向有着强烈的不安全感，伴侣一点点细微的举止，就会让你大动干戈（也就是高焦虑程度），那你或许属于焦虑型。</p></li><li><p>如果与伴侣太过亲密会让你感到不适，并且你会将独立和自由看得高于亲密关系（也就是高回避程度），不仅如此，你也不会过度理会伴侣的感受以及对你的评价（也就是低焦虑程度），那你或许属于回避型。</p></li><li><p>如果你既不喜欢过分亲密，又非常在意伴侣是否一如既往地爱你，那你就属于比较罕见的焦虑——回避型。这种依恋风格的人群占总人口的比例很小，若你是其中之一，你可以借鉴焦虑型和回避型两类人群的相关调节知识。</p></li></ul><p>始于生命的头几个月</p><p>这些依恋风格到底从何而来呢？非常有趣的是，这些风格其实是是由婴儿的行为划分而来的。这些不同的风格种类，最初是由研究者们通过对9~18个月大的婴儿，在陌生情境测验中的行为方式进行观察，进而分类而得的。具体情境正如前文所描述的那样，先将婴儿与父母分开，体验到压力后再让亲子重逢。</p><p>焦虑型：这一类型的婴儿，在妈妈离开房间以后会变得异常焦躁。当妈妈回来以后，他们的反应会很纠结，对于见到妈妈，表现得既高兴又生气。婴儿需要很长时间才能平静下来，而且这种平静持续的时间很短。过不了一会，就会很生气地将妈妈推开，焦躁地扭来扭去，哇地哭出来。</p><p>安全型：这个类型的婴儿在妈妈离开之后，可以看出来，他们是很焦躁的。而妈妈回来以后他们会非常高兴地迎接妈妈。婴儿只要在妈妈身边，就有足够的安全感，非常容易安抚，也很容易继续投入地玩耍。</p><p>回避型：妈妈离开房间后，这些孩子会表现得若无其事。妈妈回来以后依然无动于衷，继续玩自己的。但是这种表现还有着更深的含义，事实上婴儿的内心是有很大波澜的。研究者发现，在面对比较大的压力时，这类婴儿的心跳加速程度跟其他类型的孩子是一样的，不仅如此，他们的压力激素皮质醇水平甚至还要更高一些。</p>',12)])])}const h=p(o,[["render",i]]);export{u as __pageData,h as default};
